import { Fragment } from 'react/jsx-runtime';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { WalletItemDTO } from '~/entities/wallet/api/dtos/wallet-item';
import { useWalletHistoryListQuery } from '~/entities/wallet/api/use-wallet-history-list-query';
import { RcppaySttusCd, TrnscTypeCd } from '~/shared/api/dtos/enums';
import { useNavigate } from '~/shared/lib/hooks';
import { PATHS } from '~/shared/routes/paths';

export const RecentUseHistoryContent = () => {
  const { data: userRes } = useGetUserInfoQuery();
  const { navigate } = useNavigate();
  const cstmrNo = userRes?.tbCstmrMastr?.cstmrNo ?? '';
  const { data } = useWalletHistoryListQuery({
    search: {
      cstmrNo,
    },
  });

  const newList = data?.result.newList;

  if (!data || (newList && Object.keys(newList)?.length === 0)) {
    return (
      <div className="main-empty-state">
        <p className="empty-text">최근 이용내역이 없습니다.</p>
      </div>
    );
  }

  const moveToDetail = (item: WalletItemDTO) => {
    const search = item.vouchId ? `?vouchId=${encodeURIComponent(item.vouchId)}` : '';
    navigate(`${PATHS.myWallet.historyDetail}${item.trnscId}${search}`);
  };

  return (
    <>
      {newList &&
        Object.keys(newList)?.map((key) => (
          <Fragment key={key}>
            <div className="main-transactions-date-wrapper">
              <span className="main-tsansactions-date">{key.split(' ')[0]}</span>
              <span className="main-tsansactions-day">{key.split(' ')[1]}</span>
            </div>
            {newList[key].map((item: WalletItemDTO) => {
              const isDeposit = item.rcppaySttusCd === RcppaySttusCd.입금코드;
              const signClass = isDeposit ? 'sign-plus' : 'sign-minus';
              const sign = isDeposit ? '+' : '-';
              const typeName = item.trnscTypeCd === TrnscTypeCd.송금 && isDeposit ? '받기' : item.walletDetailSeNm;

              return (
                <div
                  className="main-transactions-wrapper row-wrapper"
                  key={item.trnscId}
                  onClick={() => moveToDetail(item)}
                >
                  <div className="main-transactions-info-wrapper">
                    <span className="main-transactions-label">{item.title}</span>
                    <div className="main-transactions-info">
                      <span className="main-transactions-time">{item.time}</span>
                      <i className="icon-main-transactions-dot"></i>
                      <span className="main-transactions-type">{typeName}</span>
                    </div>
                  </div>
                  <div className="main-transactions-value-wrapper">
                    <span className={`main-transactions-value ${signClass}`}>
                      {sign}
                      {item.trnscAmt.toLocaleString()}
                    </span>
                    <span className="main-transactions-won">원</span>
                  </div>
                </div>
              );
            })}
          </Fragment>
        ))}
    </>
  );
};
