import { useNotiBar } from '~/app/hooks/use-noti-bar';
import { WebViewRedirectionBoundary } from '~/widgets/web-view/redirection-boundary';
import { Navigation } from '~/widgets/navigation';
import { useComCodeState } from '~/entities/comcode/lib/use-comcode-state';
import { COM_CODE } from '~/entities/comcode/model/constants';
import { useShowBlockedWallet } from '~/entities/home/lib/use-show-dialog-blocked-wallet';
import { Notice } from '~/entities/home/ui/notice';
import { Payment } from '~/entities/home/ui/payment';
import { RecentUseHistory } from '~/entities/home/ui/recent-use-history';
import { Wallet } from '~/entities/home/ui/wallet';
import { LawInfo } from '~/entities/home/ui/law-info';
import { useNotificationRegister } from '~/entities/notification/lib/use-notification-register';
import { useQRScan } from '~/entities/qr-scan/lib/use-qr-scan';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { useRefreshUserInfo } from '~/entities/user/lib/use-refresh-user-info';
import { usePrefetchIssuedVoucher } from '~/entities/voucher/api/hooks/use-prefetch-issued-voucher';
import { useBlockBack } from '~/shared/lib/hooks/use-block-back';
import { BACK_BLOCKED_PATHS, PATHS } from '~/shared/routes/paths';

export const HomePage = () => {
  const { data: userRes } = useGetUserInfoQuery();
  const hasWallet = !!userRes?.tbCstmrMastr?.hasWallet;
  const cstmrNo = userRes?.tbCstmrMastr?.cstmrNo ?? '';
  const userAliasNm = userRes?.tbCstmrMastr?.aliasNm ?? '';

  useRefreshUserInfo();
  useNotificationRegister();
  useComCodeState(COM_CODE.TRANSACTION_TYPE);
  useBlockBack(BACK_BLOCKED_PATHS?.[PATHS.home]);
  useShowBlockedWallet();
  useNotiBar();
  usePrefetchIssuedVoucher({ hasWallet, cstmrNo, userAliasNm });
  const { openQRScanner } = useQRScan();

  return (
    <WebViewRedirectionBoundary>
      <div className="page-main-KBB">
        <header>
          <Navigation />
        </header>
        <main className="main-content">
          <Wallet />
          <Payment openQRScanner={openQRScanner} />
          {hasWallet && <RecentUseHistory />}
          <Notice />
          <LawInfo />
        </main>
      </div>
    </WebViewRedirectionBoundary>
  );
};
