import { addDays, startOfDay } from 'date-fns';
import { useState } from 'react';
import { useCookies } from 'react-cookie';
import { WALLET_BLOCK_POPUP_HIDE_TODAY } from '~/shared/constants/cookie';
import { overlay } from '~/shared/lib/overlay';

export const BlockedWalletDialog = () => {
  const [, setCookie] = useCookies([WALLET_BLOCK_POPUP_HIDE_TODAY]);
  const [hideToday, setHideToday] = useState(false);

  const onClickConfirm = () => {
    if (hideToday) {
      const expires = addDays(startOfDay(new Date()), 1);
      setCookie(WALLET_BLOCK_POPUP_HIDE_TODAY, true, {
        path: '/',
        expires,
      });
    }
    overlay.closeAll();
  };

  const onClickCancel = () => {
    overlay.closeAll();
  };

  return (
    <div className="modal-dialog-overlay active">
      <div className="modal-dialog-container main-modal">
        <div className="modal-dialog-content">
          <h3 className="modal-dialog-title">거래제한</h3>
          <p className="modal-dialog-reason">사유(이상거래 감지)</p>
          <p className="modal-dialog-description">
            이상거래가 감지되어 거래가 제한되었습니다. 자세한 사항은 고객센터로 문의해주세요.
          </p>
          <div className="modal-checkbox-wrapper">
            <label className="custom-checkbox-label">
              <input
                type="checkbox"
                className="custom-checkbox-input"
                checked={hideToday}
                onChange={(e) => setHideToday(e.target.checked)}
              />
              <span className="custom-checkbox-icon">
                <i className="icon-chk"></i>
              </span>
              <span className="checkbox-text">오늘은 다시 보지 않기</span>
            </label>
          </div>
        </div>
        <div className="modal-dialog-footer">
          <button type="button" className="btn-modal-cancel" onClick={onClickCancel}>
            취소
          </button>
          <button type="button" className="btn-modal-confirm" onClick={onClickConfirm}>
            확인
          </button>
        </div>
      </div>
    </div>
  );
};
