import { useBlocker } from '@use-blocker';

export const useBlockBack = (blockPaths: string[]) => {
  useBlocker(({ currentLocation, nextLocation, historyAction }) => {
    if (historyAction !== 'POP') {
      return false;
    }

    if (blockPaths.includes(currentLocation.pathname)) {
      return true;
    }

    if (blockPaths.includes(nextLocation.pathname)) {
      return true;
    }

    return false;
  });
};
