import {
  resetNoticeListQuery,
  useNoticeListInfiniteQuery,
} from '~/entities/community/api/use-notice-list-infinite-query';
import { CommunityParams } from '~/entities/community/model/types';
import { SortDirection } from '~/shared/api/dtos/enums';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { parseToDate } from '~/shared/lib/web-view-bridge';
import { PATHS } from '~/shared/routes/paths';

export const NoticeContent = () => {
  const { navigate } = useNavigate();
  const { data: list, markAsRead } = useNoticeListInfiniteQuery({
    paging: {
      currentPageNo: 0,
      recordCountPerPage: 3,
      orderBy: { columnList: [{ columnName: 'registDt', sortDirection: SortDirection.내림차순 }], toSnakeCase: true },
    },
  });

  const onClickItem = async (item: CommunityParams) => {
    if (item.nttManageId) {
      markAsRead(item.nttManageId);
    }
    navigate(`${PATHS.community.noticeDetail}${item.nttManageId}`, { state: item.nttManageId });
  };

  const flattenList = list?.pages.map((page) => page?.result?.list).flat() || [];
  if (!list || flattenList.length === 0) {
    return (
      <div className="main-empty-state">
        <p className="empty-text">등록된 공지사항이 없습니다.</p>
      </div>
    );
  }

  return (
    <>
      {flattenList?.map(
        (item, index) =>
          item && (
            <div
              className="main-notice-info-wrapper"
              key={`notice_${item.nttManageId}_${index}`}
              onClick={() => onClickItem(item)}
            >
              <span className="main-notice-label">{item.nttSj}</span>
              <div className="main-notice-info">
                <span className="main-notice-time">{parseToDate(item.registDt, 'yyyy.MM.dd')}</span>
              </div>
            </div>
          ),
      )}
    </>
  );
};
